        for x in range(w):
            r,g,b = pix[x,y][:3]
            if b>r+30 and b>g+15 and b>80 and r<140:
                blues.append((x,y))
    if blues:
        bc = (sum(p[0] for p in blues)/len(blues), sum(p[1] for p in blues)/len(blues), len(blues))
    else:
        bc = None
